import { URL, URLSearchParams } from '../../mochiurl/index.js';
import {
    install as installTimers,
    setTimeout,
    clearTimeout,
    setInterval,
    clearInterval,
    setImmediate,
    clearImmediate
} from '../../mochitimers/script/index.js';

export { URL, URLSearchParams, setTimeout, clearTimeout, setInterval, clearInterval, setImmediate, clearImmediate };

export class TextEncoder {
    constructor() { this.encoding = 'utf-8'; }

    encode(input = '') {
        const s = String(input);
        const out = [];
        for (let i = 0; i < s.length; i++) {
            let cp = s.charCodeAt(i);
            if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < s.length) {
                const low = s.charCodeAt(i + 1);
                if (low >= 0xdc00 && low <= 0xdfff) {
                    cp = 0x10000 + ((cp - 0xd800) << 10) + (low - 0xdc00);
                    i++;
                }
            }
            if (cp < 0x80) {
                out.push(cp);
            } else if (cp < 0x800) {
                out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
            } else if (cp < 0x10000) {
                out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
            } else {
                out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f),
                    0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
            }
        }
        return new Uint8Array(out);
    }

    encodeInto(source = '', destination) {
        let src = source;
        let dest = destination;
        if (typeof src !== 'string' && (dest === undefined || typeof dest === 'string')) {
            const tmp = src;
            src = String(dest === undefined ? '' : dest);
            dest = tmp;
        }
        src = String(src);
        const bytes = this.encode(src);
        if (dest && typeof dest.set === 'function') {
            const n = Math.min(bytes.length, dest.length);
            for (let i = 0; i < n; i++) dest[i] = bytes[i];
            return { read: src.length, written: n };
        }
        return { read: src.length, written: 0 };
    }
}

export class TextDecoder {
    constructor(label = 'utf-8') {
        this.encoding = String(label);
        this.fatal = false;
        this.ignoreBOM = false;
    }

    decode(input) {
        let bytes;
        if (input === undefined || input === null) {
            bytes = new Uint8Array(0);
        } else if (input instanceof Uint8Array) {
            bytes = input;
        } else if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(input)) {
            bytes = new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
        } else if (typeof ArrayBuffer !== 'undefined' && input instanceof ArrayBuffer) {
            bytes = new Uint8Array(input);
        } else if (typeof input === 'string') {
            return input;
        } else {
            bytes = new Uint8Array(0);
        }

        let out = '';
        let cp = 0;
        let count = 0;
        for (let i = 0; i < bytes.length; i++) {
            const b = bytes[i];
            if (b < 0x80) {
                if (cp) { out += String.fromCodePoint(cp); cp = 0; count = 0; }
                out += String.fromCharCode(b);
            } else if ((b & 0xe0) === 0xc0) {
                if (cp) { out += String.fromCodePoint(cp); cp = 0; count = 0; }
                cp = b & 0x1f; count = 1;
            } else if ((b & 0xf0) === 0xe0) {
                if (cp) { out += String.fromCodePoint(cp); cp = 0; count = 0; }
                cp = b & 0x0f; count = 2;
            } else if ((b & 0xf8) === 0xf0) {
                if (cp) { out += String.fromCodePoint(cp); cp = 0; count = 0; }
                cp = b & 0x07; count = 3;
            } else {
                cp = (cp << 6) | (b & 0x3f);
                count++;
                if (count === 0) { out += String.fromCodePoint(cp); cp = 0; }
            }
        }
        if (cp) out += String.fromCodePoint(cp);
        return out;
    }
}

export class AbortSignal {
    constructor() {
        this.aborted = false;
        this.reason = undefined;
        this.onabort = null;
        this._listeners = [];
    }

    addEventListener(type, fn) {
        if (type === 'abort' && typeof fn === 'function') this._listeners.push(fn);
    }

    removeEventListener(type, fn) {
        if (type !== 'abort') return;
        this._listeners = this._listeners.filter((item) => item !== fn);
    }

    dispatchEvent(event) {
        if (event && event.type === 'abort') this._abort(event.reason);
        return true;
    }

    throwIfAborted() {
        if (this.aborted) throw this.reason;
    }

    _abort(reason) {
        if (this.aborted) return;
        this.aborted = true;
        this.reason = reason;
        const event = { type: 'abort', target: this, reason };
        try { if (this.onabort) this.onabort(event); } catch (e) {}
        for (const fn of this._listeners) {
            try { fn(event); } catch (e) {}
        }
        this._listeners = [];
    }

    static abort(reason) {
        const signal = new AbortSignal();
        signal._abort(reason);
        return signal;
    }

    static timeout(ms) {
        const controller = new AbortController();
        setTimeout(() => controller.abort(), ms);
        return controller.signal;
    }
}

export class AbortController {
    constructor() { this.signal = new AbortSignal(); }

    abort(reason) {
        if (reason === undefined) {
            const err = new Error('AbortError');
            err.name = 'AbortError';
            reason = err;
        }
        this.signal._abort(reason);
    }
}

function patchEncodeInto(ctor) {
    if (!ctor || typeof ctor.prototype === 'undefined') return;
    if (typeof ctor.prototype.encodeInto === 'function') return;
    ctor.prototype.encodeInto = function (source = '', destination) {
        let src = source;
        let dest = destination;
        if (typeof src !== 'string' && (dest === undefined || typeof dest === 'string')) {
            const tmp = src;
            src = String(dest === undefined ? '' : dest);
            dest = tmp;
        }
        src = String(src);
        const bytes = this.encode(src);
        if (dest && typeof dest.set === 'function') {
            const n = Math.min(bytes.length, dest.length);
            for (let i = 0; i < n; i++) dest[i] = bytes[i];
            return { read: src.length, written: n };
        }
        return { read: src.length, written: 0 };
    };
}

export function install(target = globalThis) {
    installTimers(target);
    const put = (name, value) => {
        if (typeof target[name] === 'undefined') target[name] = value;
    };
    put('URL', URL);
    put('URLSearchParams', URLSearchParams);
    put('TextEncoder', TextEncoder);
    put('TextDecoder', TextDecoder);
    put('AbortSignal', AbortSignal);
    put('AbortController', AbortController);
    patchEncodeInto(target.TextEncoder);
    if (typeof target.__mochiSleep !== 'function') {
        target.__mochiSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    }
    return target;
}

install();

export default {
    URL,
    URLSearchParams,
    TextEncoder,
    TextDecoder,
    AbortSignal,
    AbortController,
    setTimeout,
    clearTimeout,
    setInterval,
    clearInterval,
    setImmediate,
    clearImmediate,
    install
};
